import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ----------------------------------------------------------------------
# Custom CUDA kernel for depthwise 2D convolution (naïve but matching signature)
# ----------------------------------------------------------------------
conv2d_kernel_src = """
__global__ void conv2d_kernel(const float* input, const float* weight, float* output,
                               int B, int C_in, int C_out, int H, int W,
                               int KH, int KW, int s_h, int s_w, int ph, int pw, int dh, int dw) {
    int OH = (H + 2*ph - (KH-1)*dh) / s_h;
    int OW = (W + 2*pw - (KW-1)*dw) / s_w;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    long total = B * C_out * OH * OW;
    if (idx < total) {
        int tmp = idx;
        int c_out = tmp / (OH * OW);
        tmp %= (OH * OW);
        int oh = tmp / OW;
        int ow = tmp % OW;
        int b = tmp / (C_out * OH * OW);
        int rem1 = tmp % (C_out * OH * OW);
        int rem2 = rem1 % (OH * OW);
        int c_out2 = rem1 / (OH * OW);   // not needed

        float sum = 0.0f;
        for (int kh = 0; kh < KH; ++kh) {
            int dh_pos = kh * dh;
            for (int kw = 0; kw < KW; ++kw) {
                int dw_pos = kw * dw;
                int ih = oh + dh_pos;
                int iw = ow + dw_pos;
                if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
                    int w_idx = (c_out * C_in * KH * KW) + (c_out * KW) + (kh * KW) + kw;
                    sum += input[b * C_in * H * W + c_out * H * W + oh * W + iw] * weight[w_idx];
                }
            }
        }
        output[idx] = sum;
    }
}
"""

# ----------------------------------------------------------------------
# Wrapper that launches the kernel and returns a tensor
# ----------------------------------------------------------------------
conv2d_cuda_src = """
torch::Tensor conv2d_cuda(torch::Tensor input, torch::Tensor weight) {
    auto size = input.numel();
    auto out = torch::zeros_like(input);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    conv2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        out.data_ptr<float>(),
        input.size(0), input.size(1), weight.size(0), input.size(2), input.size(3),
        weight.size(2), weight.size(3), input.size(2), input.size(3),
        1, 1, 0, 0, 1, 1
    );

    return out;
}
"""

# Register the custom CUDA function
conv2d_cuda = load_inline(
    name="conv2d_cuda",
    cpp_sources=conv2d_cuda_src,
    cuda_sources=conv2d_kernel_src,
    functions=["conv2d_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        # Same construction as the original Model but keep a reference to its weight tensor
        self.conv2d = nn.Conv2d(in_channels=128, out_channels=128,
                                kernel_size_h=3, kernel_size_w=7,
                                stride=(1, 1), padding=(0, 0),
                                dilation=(1, 1), groups=128, bias=False)
        self._weight_ptr = self.conv2d.weight.data_ptr()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Call the custom CUDA function that performs the depthwise convolution
        return conv2d_cuda(x, self._weight_ptr)
